import{_ as e,o as s,c as a,a2 as i}from"./chunks/framework.CWdVbaJB.js";const k=JSON.parse('{"title":"Pricing & Cost Attribution","description":"","frontmatter":{"title":"Pricing & Cost Attribution"},"headers":[],"relativePath":"platform/pricing.md","filePath":"platform/pricing.md"}'),n={name:"platform/pricing.md"};function o(r,t,l,p,d,c){return s(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="pricing-cost-attribution" tabindex="-1">Pricing &amp; Cost Attribution <a class="header-anchor" href="#pricing-cost-attribution" aria-label="Permalink to &quot;Pricing &amp; Cost Attribution&quot;">​</a></h1><p>SHAVIRA automatically tracks the cost of every LLM call by syncing model pricing from the <a href="https://github.com/BerriAI/litellm" target="_blank" rel="noreferrer">LiteLLM pricing catalog</a> and computing per-token costs at ingest time.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LiteLLM Feed ──→ price_fetch_cache (1h TTL)</span></span>
<span class="line"><span>                       │</span></span>
<span class="line"><span>                       ▼</span></span>
<span class="line"><span>               model_prices table ◄── manual overrides</span></span>
<span class="line"><span>                       │</span></span>
<span class="line"><span>                       ▼</span></span>
<span class="line"><span>           computePricing() at ingest time</span></span>
<span class="line"><span>                       │</span></span>
<span class="line"><span>                       ▼</span></span>
<span class="line"><span>                  cost_ledger</span></span></code></pre></div><ol><li><strong>Sync</strong> — Every 24 hours the pricing sync service fetches the LiteLLM catalog, diffs it against the current <code>model_prices</code> table, and applies changes automatically.</li><li><strong>Compute</strong> — When a trace is ingested (via SDK or OTel), SHAVIRA looks up the provider/model in <code>model_prices</code> and computes cost from token counts.</li><li><strong>Store</strong> — The computed cost, pricing version, and price source are written to the <code>cost_ledger</code> table alongside the raw token counts.</li></ol><h2 id="automatic-sync" tabindex="-1">Automatic Sync <a class="header-anchor" href="#automatic-sync" aria-label="Permalink to &quot;Automatic Sync&quot;">​</a></h2><p>The pricing sync runs:</p><ul><li>Once on server startup</li><li>Every 24 hours thereafter (configurable via <code>PRICING_SYNC_INTERVAL_MS</code>)</li><li>Up to 3 retries at 5-minute intervals on failure</li></ul><p>The sync is non-blocking — a failure never crashes the server. Health status is reported in <code>GET /api/health</code> under the <code>pricingSync</code> field:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;pricingSync&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;lastRunAt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-07-11T02:00:00.000Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;nextRunAt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-07-12T02:00:00.000Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ok&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="change-alerts" tabindex="-1">Change Alerts <a class="header-anchor" href="#change-alerts" aria-label="Permalink to &quot;Change Alerts&quot;">​</a></h3><p>When any model price changes by more than 20%, SHAVIRA sends alerts through:</p><ul><li><strong>Slack</strong> — if <code>SLACK_WEBHOOK_URL</code> is set</li><li><strong>Email</strong> — if <code>ALERT_EMAIL</code> is set</li></ul><p>Alerts include a breakdown of which models changed, old vs. new per-token prices, and the maximum percentage change. New model additions never trigger alerts.</p><h2 id="price-source-tiers" tabindex="-1">Price Source Tiers <a class="header-anchor" href="#price-source-tiers" aria-label="Permalink to &quot;Price Source Tiers&quot;">​</a></h2><p>Every cost computation is tagged with a <code>priceSource</code> indicating confidence:</p><table tabindex="0"><thead><tr><th>Source</th><th>Meaning</th></tr></thead><tbody><tr><td><code>priced</code></td><td>Full token-level cost computed from catalog pricing</td></tr><tr><td><code>priced_partial</code></td><td>Cost computed but missing cached token breakdown (cache read/write rates exist but the SDK didn&#39;t report cached token counts)</td></tr><tr><td><code>estimated</code></td><td>Approximate cost from partial data</td></tr><tr><td><code>unpriced_missing_model</code></td><td>Token counts present but no pricing entry found for this model</td></tr><tr><td><code>unpriced_missing_usage</code></td><td>Pricing entry exists but the trace has no token counts</td></tr><tr><td><code>reported_only</code></td><td>Only the SDK-reported cost is available (no token counts to verify)</td></tr></tbody></table><h2 id="token-dimensions" tabindex="-1">Token Dimensions <a class="header-anchor" href="#token-dimensions" aria-label="Permalink to &quot;Token Dimensions&quot;">​</a></h2><p>SHAVIRA computes cost across multiple token dimensions when available:</p><table tabindex="0"><thead><tr><th>Dimension</th><th>Description</th></tr></thead><tbody><tr><td>Input tokens</td><td>Prompt/input tokens</td></tr><tr><td>Output tokens</td><td>Completion/output tokens</td></tr><tr><td>Cached read tokens</td><td>Tokens served from provider cache (e.g., Anthropic prompt caching)</td></tr><tr><td>Cached write tokens</td><td>Tokens written to provider cache</td></tr><tr><td>Reasoning tokens</td><td>Thinking/reasoning tokens (e.g., Claude extended thinking, OpenAI o-series)</td></tr></tbody></table><p>The system detects cached token fields automatically from multiple SDK formats (snake_case, camelCase, nested <code>usage.prompt_tokens_details</code>, etc.).</p><h2 id="model-resolution" tabindex="-1">Model Resolution <a class="header-anchor" href="#model-resolution" aria-label="Permalink to &quot;Model Resolution&quot;">​</a></h2><p>When looking up prices, SHAVIRA resolves models through a multi-step fallback:</p><ol><li><strong>Normalize</strong> — Provider and model names are lowercased, version suffixes stripped, namespaces removed (e.g., <code>anthropic.claude-sonnet-4-5-v1</code> → <code>anthropic</code> / <code>claude-sonnet-4-5</code>)</li><li><strong>Alias lookup</strong> — Check <code>model_aliases</code> table for canonical names</li><li><strong>Exact match</strong> — Look for an exact entry in <code>model_prices</code></li><li><strong>Prefix match</strong> — Match the longest prefix (e.g., <code>gpt-4o-2024-08-06</code> matches a <code>gpt-4o</code> prefix entry)</li><li><strong>Regex match</strong> — Manual regex patterns (admin-created only)</li></ol><h2 id="manual-price-overrides" tabindex="-1">Manual Price Overrides <a class="header-anchor" href="#manual-price-overrides" aria-label="Permalink to &quot;Manual Price Overrides&quot;">​</a></h2><p>Admins can add custom prices for models not in the LiteLLM catalog (e.g., self-hosted models on Ollama or vLLM):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:4000/api/admin/pricing/custom</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer shv_admin_key&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;provider&quot;: &quot;local&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;modelPattern&quot;: &quot;my-finetuned-llama&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;matchType&quot;: &quot;exact&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;inputPerToken&quot;: 0.00015,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;outputPerToken&quot;: 0.00022,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;pricingVersion&quot;: &quot;custom-2026-07&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span></span></code></pre></div><p>Manual prices (<code>source: &quot;manual&quot;</code>) are never overwritten by the automatic sync.</p><h2 id="retroactive-recomputation" tabindex="-1">Retroactive Recomputation <a class="header-anchor" href="#retroactive-recomputation" aria-label="Permalink to &quot;Retroactive Recomputation&quot;">​</a></h2><p>After a pricing sync or manual override, you can retroactively recalculate costs for historical traces:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:4000/api/admin/pricing/recompute</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer shv_admin_key&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;from&quot;: &quot;2026-07-01T00:00:00Z&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;to&quot;: &quot;2026-07-11T00:00:00Z&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;projectId&quot;: &quot;proj-001&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span></span></code></pre></div><p>This re-runs <code>computePricing()</code> against the current <code>model_prices</code> for each matching <code>cost_ledger</code> row (batched at 500 rows per call).</p><h2 id="preview-apply-flow" tabindex="-1">Preview &amp; Apply Flow <a class="header-anchor" href="#preview-apply-flow" aria-label="Permalink to &quot;Preview &amp; Apply Flow&quot;">​</a></h2><p>The sync uses a two-step preview/apply flow for safety:</p><ol><li><strong>Preview</strong> — <code>POST /api/admin/pricing/sync</code> fetches the latest LiteLLM feed, diffs against current prices, and returns a preview with all changes and unknown models. The preview expires after 15 minutes.</li><li><strong>Apply</strong> — <code>POST /api/admin/pricing/apply</code> applies a preview by ID. If upstream prices changed between preview and apply, a conflict is detected and a fresh preview is returned instead.</li></ol><p>The automatic scheduler handles both steps internally. The admin API exposes them for manual control.</p><h2 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>PRICING_SYNC_INTERVAL_MS</code></td><td><code>86400000</code> (24h)</td><td>How often the sync runs</td></tr><tr><td><code>SLACK_WEBHOOK_URL</code></td><td>—</td><td>Slack webhook for &gt;20% price change alerts</td></tr><tr><td><code>ALERT_EMAIL</code></td><td>—</td><td>Email address for &gt;20% price change alerts</td></tr></tbody></table><h2 id="api-endpoints" tabindex="-1">API Endpoints <a class="header-anchor" href="#api-endpoints" aria-label="Permalink to &quot;API Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>GET /api/pricing</code></td><td>Authenticated</td><td>List active prices and recent sync history</td></tr><tr><td><code>POST /api/admin/pricing/sync</code></td><td>Admin</td><td>Create a pricing sync preview</td></tr><tr><td><code>POST /api/admin/pricing/apply</code></td><td>Admin</td><td>Apply a preview by ID</td></tr><tr><td><code>POST /api/admin/pricing/custom</code></td><td>Admin</td><td>Add a manual price override</td></tr><tr><td><code>POST /api/admin/pricing/recompute</code></td><td>Admin</td><td>Recompute costs for historical traces</td></tr></tbody></table><p>See the <a href="/shavira-docs/api-reference/admin.html">Admin API Reference</a> for full request/response details.</p>`,41)])])}const u=e(n,[["render",o]]);export{k as __pageData,u as default};
